using System; using System.Collections.Generic; using System.Globalization;
namespace Dayu.Core {
 public enum ValType { Int, Long, Double, Bool, Char, Str, Null }
 // 小数按 C++ cout 默认口径打印（6 位有效数字、指数小写 e），VM 和 g++ 对拍才不会因格式差异判错
 public readonly struct Val { public readonly ValType Type; public readonly long I; public readonly double D; public readonly string S; public Val(ValType t,long i=0,double d=0,string s=null){Type=t;I=i;D=d;S=s;} public static Val Int(long x)=>new Val(ValType.Int,x); public static Val Long(long x)=>new Val(ValType.Long,x); public static Val Double(double x)=>new Val(ValType.Double,0,x); public static Val Bool(bool x)=>new Val(ValType.Bool,x?1:0); public static Val Char(char x)=>new Val(ValType.Char,x); public static Val Str(string x)=>new Val(ValType.Str,0,0,x??""); public static Val Null()=>new Val(ValType.Null); public bool AsBool()=>Type==ValType.Bool?I!=0:Type==ValType.Int||Type==ValType.Long?I!=0:Type==ValType.Double?D!=0:!string.IsNullOrEmpty(S); public long AsLong()=>Type==ValType.Double?(long)D:I; public double AsDouble()=>Type==ValType.Double?D:I; public string AsString()=>Type==ValType.Char?((char)I).ToString():Type==ValType.Str?S:ToDisplayString(); public string ToDisplayString(){if(Type==ValType.Bool)return AsBool()?"true":"false";if(Type==ValType.Double)return Fmt(D);if(Type==ValType.Char)return ((char)I).ToString();if(Type==ValType.Str)return S??"";if(Type==ValType.Null)return "null";return I.ToString(CultureInfo.InvariantCulture);} static string Fmt(double d){if(double.IsNaN(d))return "nan";if(double.IsPositiveInfinity(d))return "inf";if(double.IsNegativeInfinity(d))return "-inf";return d.ToString("G6",CultureInfo.InvariantCulture).Replace("E","e");} }
 public sealed class StructSnap { public string Id,Kind,Name; public List<object> Items=new List<object>(); }
 public sealed class TraceEvent { public int I; public string Kind,Uid,Text,Output; public int Depth; public Dictionary<string,object> Vars=new Dictionary<string,object>(); public Dictionary<string,List<object>> Arrays=new Dictionary<string,List<object>>(); public List<StructSnap> Structs=new List<StructSnap>(); }
 public sealed class VmError { public string Message,NodeUid; public int Seq; }
 public sealed class RunResult { public bool Ok; public string Output; public List<TraceEvent> Events=new List<TraceEvent>(); public VmError Error; public int Steps; }
}
